package helper

import (
	"errors"
	"strings"
	"time"

	"code.byted.org/security/go-spiffe-v2/spiffeid"
	"github.com/go-jose/go-jose/v3/jwt"
)

const (
	SchemaNS  = "ns"
	SchemaR   = "r"
	SchemaVDC = "vdc"
	SchemaID  = "id"

	tokenTypeGDPR = "gdpr"
	tokenTypeZTI  = "zti"
)

// Identity Defined with spiffeID
type ZeroTrustIdentity struct {
	// Should not be empty
	SpiffeID spiffeid.ID
	Expiry   time.Time
	// can be generated by ValidateZTI
	Namespace string
	Region    string
	VDC       string
	ID        string
}

func (zti *ZeroTrustIdentity) ValidateZTI() error {
	if zti.SpiffeID.IsZero() {
		return errors.New("the SPIFFE ID is the zero value")
	}

	if zti.Expiry.IsZero() {
		return errors.New("the expiry is zero, we do not support zero expiry as token without expiration")
	}

	// parse the path of spiffeID into Namespace, Region, VDC and ID
	for _, schemas := range strings.Split(zti.SpiffeID.Path(), "/") {
		schema := strings.SplitN(schemas, ":", 2)
		if len(schema) != 2 {
			continue
		}

		key := schema[0]
		value := schema[1]

		switch strings.ToLower(key) {
		case SchemaNS:
			zti.Namespace = value
		case SchemaR:
			zti.Region = value
		case SchemaVDC:
			zti.VDC = value
		case SchemaID:
			zti.ID = value
		}
	}
	return nil
}

func (zti *ZeroTrustIdentity) IsValidated() bool {
	return strings.TrimSpace(zti.ID) != ""
}

func (zti *ZeroTrustIdentity) GetLegacyIdentityFromZTI() (*LegacyIdentity, error) {
	if !zti.IsValidated() {
		if err := zti.ValidateZTI(); err != nil {
			return nil, err
		}
	}

	// without legacy ID added, so we need to transform ZTI into legacy ID format
	// in this case, AuthorityChain and Extension is not supported
	identity := &LegacyIdentity{
		Version:   0,
		Authority: zti.Namespace,
	}
	identity.ExpireTime = zti.Expiry.Unix()
	if strings.EqualFold(zti.Namespace, "user") {
		identity.PrimaryAuthType = "user"
		identity.User = zti.ID
	} else {
		identity.PrimaryAuthType = "psm"
		identity.PSM = zti.ID
	}
	return identity, nil
}

// LegacyIdentity is defined to provide backward compatibility of identity from gdpr token
type LegacyIdentity struct {
	Version         int64             `json:"version"`
	Authority       string            `json:"authority"`
	AuthorityChain  []string          `json:"authorityChain,omitempty"`
	PrimaryAuthType string            `json:"primaryAuthType"`
	PSM             string            `json:"psm"`
	User            string            `json:"user"`
	ExpireTime      int64             `json:"expireTime"`
	Extension       map[string]string `json:"extension,omitempty"`
}

type SyncInformation struct {
	// Token Type
	TokenType string `json:"tokenType"`

	// Token Source
	TokenSource string `json:"tokenSource"`

	// Last Sync Time
	LastSyncTime time.Time `json:"lastSyncTime"`

	// KeyID is the key id of the token, only for zti token
	KeyID string `json:"keyID"`

	// TrustDomain is the trust domain of the token, only for zti token
	TrustDomain string `json:"trustDomain"`

	// LegacyIdentity
	*LegacyIdentity `json:"legacyIdentity"`
}

func syncInformation() (s *SyncInformation, err error) {
	s = &SyncInformation{
		TokenType:      "unknown",
		TokenSource:    tokenSource,
		LastSyncTime:   time.Now(),
		LegacyIdentity: &LegacyIdentity{},
	}

	jwtToken, err := jwt.ParseSigned(globalToken)
	if err != nil {
		return s, err
	}

	// gdpr token does not have KeyID in the token header
	if len(jwtToken.Headers) < 1 || isEmptyString(jwtToken.Headers[0].KeyID) {
		if err := jwtToken.UnsafeClaimsWithoutVerification(s.LegacyIdentity); err != nil {
			return s, err
		}
		s.TokenType = tokenTypeGDPR
		return s, nil
	}

	// support decode JWT-SVID when received token string is JWT-SVID
	zti, err := decodeIdentityFromTokenString(globalToken)
	if err != nil {
		return s, err
	}

	s.LegacyIdentity, err = zti.GetLegacyIdentityFromZTI()
	if err != nil {
		return s, err
	}

	s.TrustDomain = zti.SpiffeID.TrustDomain().IDString()
	s.KeyID = jwtToken.Headers[0].KeyID
	s.TokenType = tokenTypeZTI

	return
}
